using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

// --- Train the model at startup ---
var mlContext = new MLContext(seed: 42);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");

// Load with Churned as string ("Yes"/"No"), then map to boolean Label
IDataView dataView = mlContext.Data.LoadFromTextFile<RawCustomerData>(
    dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" → true/false
var mappingPipeline = mlContext.Transforms.CustomMapping<RawCustomerData, LabelMapping>(
    (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
    contractName: "ChurnedToLabel");

var mappedData = mappingPipeline.Fit(dataView).Transform(dataView);

var split = mlContext.Data.TrainTestSplit(mappedData, testFraction: 0.2);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(RawCustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(RawCustomerData.Age),
        nameof(RawCustomerData.Income),
        "RegionEncoded",
        nameof(RawCustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate on the test set
