1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // --- Train the model at startup ---
8. var mlContext = new MLContext(seed: 42);
9. 
10. var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");
11. 
12. // Load with Churned as string ("Yes"/"No"), then map to boolean Label
13. IDataView dataView = mlContext.Data.LoadFromTextFile<RawCustomerData>(
14.     dataPath, hasHeader: true, separatorChar: ',');
15. 
16. // Map "Yes"/"No" → true/false
17. var mappingPipeline = mlContext.Transforms.CustomMapping<RawCustomerData, LabelMapping>(
18.     (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
19.     contractName: "ChurnedToLabel");
20. 
21. var mappedData = mappingPipeline.Fit(dataView).Transform(dataView);
22. 
23. var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(RawCustomerData.Region))
24.     .Append(mlContext.Transforms.Concatenate("Features",
25.         nameof(RawCustomerData.Age),
26.         nameof(RawCustomerData.Income),
27.         "RegionEncoded",
28.         nameof(RawCustomerData.PurchaseHistory)))
29.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
30.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
31.         labelColumnName: "Label", featureColumnName: "Features"));
32. 
33. long rowCount = mappedData.GetColumn<bool>("Label").LongCount();
34. 
35. ITransformer model;
36. if (rowCount >= 10)
37. {
38.     // Enough data to hold out a test set
39.     var split = mlContext.Data.TrainTestSplit(mappedData, testFraction: 0.2);
40.     model = pipeline.Fit(split.TrainSet);
41.     var predictions = model.Transform(split.TestSet);
42.     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
43.     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
44. }
45. else
46. {
47.     // Too few rows for a meaningful split — train on all data
48.     model = pipeline.Fit(mappedData);
49.     Console.WriteLine($"Model trained on all {rowCount} rows (dataset too small for train/test split).");
50. }
51. 
52. // Save model & register pooled prediction engine
53. var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");
54. mlContext.Model.Save(model, mappedData.Schema, modelPath);
55. 
56. builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
57.     .FromFile(modelPath);
58. 
59. var app = builder.Build();
60. 
61. app.MapPost("/predict", (
62.     PredictionEnginePool<CustomerInput, ChurnPrediction> pool,
63.     CustomerInput input) =>
64. {
65.     var prediction = pool.Predict(input);
66.     return Results.Ok(new
67.     {
68.         WillChurn = prediction.PredictedLabel,
69.         Confidence = prediction.Probability
70.     });
71. });
72. 
73. app.Run();
