 using Microsoft.ML;
 using Microsoft.ML.Data;
 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // --- Train the model at startup ---
 var mlContext = new MLContext(seed: 42);

 var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "customers.csv");

 // Load with Churned as string ("Yes"/"No"), then map to boolean Label
 IDataView dataView = mlContext.Data.LoadFromTextFile<RawCustomerData>(
     dataPath, hasHeader: true, separatorChar: ',');

 // Map "Yes"/"No" → true/false
 var mappingPipeline = mlContext.Transforms.CustomMapping<RawCustomerData, LabelMapping>(
     (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
     contractName: "ChurnedToLabel");

 var mappedData = mappingPipeline.Fit(dataView).Transform(dataView);

 var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(RawCustomerData.Region))
     .Append(mlContext.Transforms.Concatenate("Features",
         nameof(RawCustomerData.Age),
         nameof(RawCustomerData.Income),
         "RegionEncoded",
         nameof(RawCustomerData.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 long rowCount = mappedData.GetColumn<bool>("Label").LongCount();

 ITransformer model;
 if (rowCount >= 10)
 {
     // Enough data to hold out a test set
     var split = mlContext.Data.TrainTestSplit(mappedData, testFraction: 0.2);
     model = pipeline.Fit(split.TrainSet);
     var predictions = model.Transform(split.TestSet);
     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
     Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 else
 {
     // Too few rows for a meaningful split — train on all data
     model = pipeline.Fit(mappedData);
     Console.WriteLine($"Model trained on all {rowCount} rows (dataset too small for train/test split).");
 }

 // Save model & register pooled prediction engine
 var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");
 mlContext.Model.Save(model, mappedData.Schema, modelPath);

 builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (
     PredictionEnginePool<CustomerInput, ChurnPrediction> pool,
     CustomerInput input) =>
 {
     var prediction = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = prediction.PredictedLabel,
         Confidence = prediction.Probability
     });
 });

 app.Run();

 // --- Data models ---

